
async function getAuthHeader() {
    const headers = { 'Content-Type': 'application/json' };
    try {
        let client = window.supabaseClient || window.supabase;
        if (!client && typeof supabase !== 'undefined' && supabase.createClient) {
            // Skapa klient om miljövariabler finns i window
            if (window.SUPABASE_URL && window.SUPABASE_ANON_KEY) {
                window.supabaseClient = supabase.createClient(window.SUPABASE_URL, window.SUPABASE_ANON_KEY);
                client = window.supabaseClient;
            }
        }
        if (client && client.auth) {
            const { data } = await client.auth.getSession();
            if (data && data.session && data.session.access_token) {
                headers['Authorization'] = `Bearer ${data.session.access_token}`;
                return headers;
            }
        }
    } catch (e) {
        console.warn('[FALK Chat] Token-fel:', e);
    }

    const localEmail = localStorage.getItem('falk_user_email');
    if (localStorage.getItem('falk_user_logged_in') === 'true' && localEmail) {
        headers['X-User-Email'] = localEmail;
        headers['Authorization'] = `Bearer mock_logged_in_${localEmail}`;
    }
    return headers;
}


// UTILITY: Inaktivera/aktivera inmatningsfält under anrop
function setInputLock(isLocked) {
    const inputEl = document.getElementById('chat-input');
    const sendBtns = document.querySelectorAll('button[onclick*="sendMessage"]');
    
    if (inputEl) {
        inputEl.disabled = isLocked;
        if (isLocked) {
            inputEl.classList.add('opacity-60', 'cursor-not-allowed');
        } else {
            inputEl.classList.remove('opacity-60', 'cursor-not-allowed');
            inputEl.focus();
        }
    }
    
    sendBtns.forEach(btn => {
        btn.disabled = isLocked;
        if (isLocked) {
            btn.classList.add('opacity-50', 'pointer-events-none');
        } else {
            btn.classList.remove('opacity-50', 'pointer-events-none');
        }
    });
}

// UTILITY: Visa/ta bort tillfällig "FALK tänker..."-bubbla
function showTypingIndicator() {
    const container = document.getElementById('messages');
    if (!container) return;

    removeTypingIndicator(); // Rensa om det finns en gammal

    const loaderDiv = document.createElement('div');
    loaderDiv.id = 'falk-typing-indicator';
    loaderDiv.className = 'flex items-center space-x-2 p-4 rounded-2xl bg-[#F8F4EC] border border-[#A8BFA1]/40 max-w-[80%] my-2 animate-pulse';
    loaderDiv.innerHTML = `
        <span class="text-xs font-serif italic text-[#4E5C4B]">FALK samlar sina tankar</span>
        <div class="flex space-x-1 items-center">
            <div class="w-1.5 h-1.5 bg-[#C57B57] rounded-full animate-bounce" style="animation-delay: 0ms"></div>
            <div class="w-1.5 h-1.5 bg-[#C57B57] rounded-full animate-bounce" style="animation-delay: 150ms"></div>
            <div class="w-1.5 h-1.5 bg-[#C57B57] rounded-full animate-bounce" style="animation-delay: 300ms"></div>
        </div>
    `;
    container.appendChild(loaderDiv);
    container.scrollTop = container.scrollHeight;
}

function removeTypingIndicator() {
    const loaderDiv = document.getElementById('falk-typing-indicator');
    if (loaderDiv) loaderDiv.remove();
}

function appendErrorMessage(msgText) {
    const container = document.getElementById('messages');
    if (!container) return;

    const errDiv = document.createElement('div');
    errDiv.className = 'p-4 rounded-2xl bg-[#C57B57]/10 border border-[#C57B57]/30 text-[#4E5C4B] text-xs font-serif italic max-w-[85%] my-2';
    errDiv.innerText = msgText || "Ett tillfälligt avbrott uppstod. Låt oss ta ett andetag och försöka igen.";
    container.appendChild(errDiv);
    container.scrollTop = container.scrollHeight;
}

import { supabaseClient } from './config.js';

let activeSessionId = null;
let currentSessionId = null;
let userToken = null;
let isSendingMessage = false;

export function initChat() {
    console.log('[FALK Chat] Modul initialiserad.');
}

export function setAppState(state) {
    console.log('[FALK UI Engine] Symmetriskt tillståndsskifte till:', state);
    
    const onboardingEl = document.getElementById('onboarding-cards-wrapper');
    const chatEl = document.getElementById('chat-container');
    const sidebar = document.getElementById('sidebar');
    const backdrop = document.getElementById('sidebar-backdrop');
                   
    // Stäng sidomenyn genom transform – ALDRIG genom 'hidden' på sidebar
    if (sidebar) {
        sidebar.classList.remove('translate-x-0');
        sidebar.classList.add('-translate-x-full');
        sidebar.classList.remove('hidden'); // Säkerställ att hidden aldrig ligger kvar
    }
    if (backdrop) {
        backdrop.classList.add('hidden');
    }

    if (state === 'chat') {
        if (onboardingEl) onboardingEl.classList.add('hidden-force');
        if (chatEl) chatEl.classList.remove('hidden-force');
    } else if (state === 'page1' || state === 'home' || state === 'onboarding') {
        if (onboardingEl) onboardingEl.classList.remove('hidden-force');
        if (chatEl) {
            chatEl.classList.add('hidden-force');
            const msgs = document.getElementById('messages');
            if (msgs) msgs.innerHTML = '';
        }
    }
}
if (typeof window !== 'undefined') {
    window.setAppState = setAppState;
}
if (typeof window !== 'undefined') {
    window.setAppState = setAppState;
}

export function appendMessage(role, text) {
    const container = document.getElementById('messages') || 
                      document.getElementById('chat-messages') || 
                      document.querySelector('.chat-wrapper') ||
                      document.querySelector('main');
                      
    if (!container) return;

    const msgDiv = document.createElement('div');
    if (role === 'user') {
        msgDiv.className = "flex justify-end my-3";
        msgDiv.innerHTML = `<div class="bg-[#3e5346] text-white p-4 rounded-2xl max-w-xl text-left shadow-sm">${text}</div>`;
    } else {
        msgDiv.className = "flex justify-start my-3";
        msgDiv.innerHTML = `<div class="bg-white text-gray-800 p-4 rounded-2xl max-w-xl text-left shadow-sm border border-gray-100">${text}</div>`;
    }

    container.appendChild(msgDiv);
    container.scrollTop = container.scrollHeight;
}

export async function sendMessage(customText = null) {
    if (isSendingMessage) return;

    const inputEl = document.getElementById('chat-input') || 
                    document.querySelector('input[type="text"]') || 
                    document.querySelector('textarea');
                    
    const text = (typeof customText === 'string') ? customText : (inputEl ? inputEl.value.trim() : '');
    if (!text) return;

    setAppState('chat');

    if (inputEl && typeof customText !== 'string') {
        inputEl.value = '';
    }

    appendMessage('user', text);
    isSendingMessage = true;

    try {
        const response = await fetch('/chat', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ message: text, session_id: activeSessionId })
        });

        if (!response.ok) {
            throw new Error(`Serverstatus: ${response.status}`);
        }

        const data = await response.json();
        const reply = data.response || data.reply || data.message || "FALK kunde inte generera ett svar.";
        appendMessage('assistant', reply);
    } catch (err) {
        console.error('[FALK Chat Error]', err);
        appendMessage('assistant', "Jag behövde stanna upp ett ögonblick. Kan du dela din reflektion igen?");
    } finally {
        isSendingMessage = false;
    }
}

export function selectPrompt(promptText) {
    console.log('[FALK Chat] selectPrompt anropad:', promptText);
    setAppState('chat');
    sendMessage(promptText);
}

export function selectOnboarding(promptText) {
    console.log('[FALK Chat] selectOnboarding anropad:', promptText);
    setAppState('chat');
    sendMessage(promptText);
}

export function startNewChat() {
    console.log('[FALK Engine] Nollställer vyn och startar onboarding.');
    
    // 1. Återställ sessions-state
    if (typeof window !== 'undefined') {
        window.activeSessionId = null;
        window.currentSessionId = null;
    }

    // 2. Rensa meddelandebubblor ur DOM-trädet
    const container = document.getElementById('messages') || 
                      document.getElementById('chat-messages') || 
                      document.querySelector('.chat-wrapper');
    if (container) {
        container.innerHTML = '';
    }

    // 3. Tvinga state-skifte till page1 / onboarding
    if (typeof setAppState === 'function') {
        setAppState('page1');
    } else if (typeof window.setAppState === 'function') {
        window.setAppState('page1');
    }
}

if (typeof window !== 'undefined') {
    window.activeSessionId = activeSessionId;
    window.currentSessionId = currentSessionId;
    window.userToken = userToken;
    window.isSendingMessage = isSendingMessage;
    window.sendMessage = sendMessage;
    window.selectPrompt = selectPrompt;
    window.selectOnboarding = selectOnboarding;
    window.startNewChat = startNewChat;
    window.setAppState = setAppState;
    window.appendMessage = appendMessage;
    window.initChat = initChat;
}

if (typeof window !== 'undefined') {
    window.startNewChat = startNewChat;
    window.createNewSession = startNewChat;
}

export function toggleMenu() {
    const sidebar = document.getElementById('sidebar');
    const backdrop = document.getElementById('sidebar-backdrop');
    if (!sidebar || !backdrop) {
        console.warn('[FALK UI] Meny-element saknas i DOM.');
        return;
    }

    // Ta bort eventuell felaktig hidden-klass på sidebar
    sidebar.classList.remove('hidden');

    const isHidden = sidebar.classList.contains('-translate-x-full');
    if (isHidden) {
        sidebar.classList.remove('-translate-x-full');
        sidebar.classList.add('translate-x-0');
        backdrop.classList.remove('hidden');
    } else {
        sidebar.classList.remove('translate-x-0');
        sidebar.classList.add('-translate-x-full');
        backdrop.classList.add('hidden');
    }
}
if (typeof window !== 'undefined') {
    window.toggleMenu = toggleMenu;
}
export function handlePaywallTrigger() {
    console.warn('[FALK Chat] Gästgräns nådd (Paywall aktiverad).');
    
    // 1. Ta bort laddningsindikator och lås upp input
    if (typeof removeTypingIndicator === 'function') removeTypingIndicator();
    if (typeof setInputLock === 'function') setInputLock(false);

    // 2. Injektera ett elegant Paywall-kort i chatten
    const container = document.getElementById('messages');
    if (container) {
        const paywallDiv = document.createElement('div');
        paywallDiv.className = 'p-5 rounded-2xl bg-[#C57B57]/15 border border-[#C57B57]/40 text-[#4E5C4B] max-w-[90%] my-3 space-y-2';
        paywallDiv.innerHTML = `
            <div class="font-bold text-sm text-[#4E5C4B] flex items-center gap-2">
                <span>🔒</span> Du har nått din gratis gästkvot
            </div>
            <p class="text-xs font-serif italic text-[#4E5C4B]/90">
                Skapa ett kostnadsfritt konto eller logga in för att fortsätta dina samtal med FALK och spara din historik.
            </p>
            <button onclick="if(window.openAuthModal) window.openAuthModal();" 
                    class="mt-2 bg-[#C57B57] text-white text-xs px-4 py-2 rounded-xl font-medium hover:bg-[#4E5C4B] transition">
                Logga in / Skapa konto
            </button>
        `;
        container.appendChild(paywallDiv);
        container.scrollTop = container.scrollHeight;
    }

    // 3. Öppna Auth-modalen automatiskt
    if (typeof window.openAuthModal === 'function') {
        window.openAuthModal();
    }
}
if (typeof window !== 'undefined') {
    window.handlePaywallTrigger = handlePaywallTrigger;
}
